mapper.select:
select COUNT(*)
from wms_approve_record_detail ward
left join wms_approve_record war on war.serial_number = ward.approve_record_serial_number
where
    war.bool_delete_enum = 0
  and war.status = #{status}
  and ward.bool_delete_enum = 0
  and ward.status = #{status}
  and ward.check_user_id = #{currentUserId}
  and ward.flow_type != #{flowType}

    and war.component_name in
    
        #{componentName}
    


    and war.approve_source = #{approveSource}
